<?php require __DIR__.'/includes/bootstrap.php';require_interaction_permission();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Méthode non autorisée.');}verify_csrf();$id=(int)($_POST['game_id']??0);$s=$pdo->prepare('SELECT id FROM games WHERE id=:id');$s->execute(['id'=>$id]);if(!$s->fetch()){flash('Jeu introuvable.','error');redirect('index.php');}$s=$pdo->prepare('SELECT 1 FROM favorites WHERE user_id=:u AND game_id=:g');$s->execute(['u'=>current_user()['id'],'g'=>$id]);if($s->fetch()){$pdo->prepare('DELETE FROM favorites WHERE user_id=:u AND game_id=:g')->execute(['u'=>current_user()['id'],'g'=>$id]);flash('Retiré des favoris.','success');}else{$pdo->prepare('INSERT IGNORE INTO favorites(user_id,game_id) VALUES(:u,:g)')->execute(['u'=>current_user()['id'],'g'=>$id]);flash('Ajouté aux favoris.','success');}redirect('game.php?id='.$id);
